/* Theme coverage and researcher-authored synthesis, stored with existing themes. */
(()=>{
 'use strict';
 const C=window.REICore,keys=['conclusion','agreement','disagreement','gaps'];
 const labels=['Your theme interpretation','Where findings agree','Disagreement / alternative explanations','Open questions / boundaries'];
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const project=()=>window.REIWorkbench.getProject();
 const draftKey=(p,id)=>'rei-theme-draft-'+p.id+'-'+id;
 function trail(p,n){const s=p.papers.find(s=>s.id===n.paperId);return `<li><h5>E${p.evidence.indexOf(n)+1} · ${esc(s?.title||'Source removed')}</h5><p>${esc(n.findings||'Finding not recorded')}</p><dl>${[['method','Method'],['context','Context'],['limitations','Limitations'],['locator','Location']].map(([key,label])=>`<div><dt>${label}</dt><dd>${esc(n[key]||'Not recorded')}</dd></div>`).join('')}</dl><div class="actions"><a class="text-link" href="#research/${esc(p.id)}/evidence" data-focus-evidence="${esc(n.id)}">Open E${p.evidence.indexOf(n)+1}</a><a class="text-link" href="#research/${esc(p.id)}/reader" data-read-source="${esc(n.paperId)}">Read original source</a></div></li>`}
 function mount(){const p=project(),overview=document.querySelector('.wb-synthesis-overview');if(!p||!overview)return;const w=C.normalize(p),coded=new Set(w.coding.map(c=>c.evidenceId)),uncoded=p.evidence.filter(n=>!coded.has(n.id));overview.children[1].querySelector('strong').textContent=p.evidence.length-uncoded.length;
 overview.insertAdjacentHTML('afterend',`<section class="wb-section synthesis-queue"><h3>Evidence waiting for a theme</h3><p>${uncoded.length} of ${p.evidence.length} notes are uncoded. Coding marks relevance to a theme; it does not mean agreement.</p>${uncoded.length?`<details><summary>Review ${uncoded.length} uncoded ${uncoded.length===1?'note':'notes'}</summary><ul class="synthesis-uncoded">${uncoded.map(n=>`<li><div><strong>E${p.evidence.indexOf(n)+1} · ${esc(p.papers.find(s=>s.id===n.paperId)?.title)}</strong><p>${esc(n.findings||'Finding not recorded')}</p></div><div class="actions"><a class="text-link" href="#research/${esc(p.id)}/evidence" data-focus-evidence="${esc(n.id)}">Inspect evidence</a>${w.codes.length?`<button class="button secondary" data-code-note="${esc(n.id)}">Choose a theme</button>`:'<span>Add a theme below to begin.</span>'}</div></li>`).join('')}</ul></details>`:p.evidence.length?'<p>Every evidence note has a theme. Review the coverage and limitations before writing your interpretation.</p>':'<p>Add source-linked notes in Evidence to begin.</p>'}</section>`);
 document.querySelectorAll('.wb-theme').forEach((el,i)=>{const code=w.codes[i],coverage=C.themeCoverage(p,code.id);el.dataset.themeId=code.id;el.insertAdjacentHTML('beforeend',`<div class="theme-depth"><p class="theme-coverage">${coverage.notes.length} evidence notes · ${coverage.sources.length} distinct sources</p><p>${coverage.notes.length?`${coverage.missingLimitations.length} notes need limitations · ${coverage.missingLocations.length} need source locations`:'No evidence coded here yet. Use the coding form below.'}</p><details class="theme-trail"><summary>Inspect evidence coverage</summary>${coverage.notes.length?`<ul>${coverage.notes.map(n=>trail(p,n)).join('')}</ul>`:'<p>Code evidence before drawing a conclusion.</p>'}</details><details class="theme-writing"><summary>Write a theme conclusion</summary><p>Explain the pattern in your own words. Coding alone does not establish agreement or quality.</p><form class="theme-conclusion" data-theme="${esc(code.id)}">${keys.map((key,i)=>`<label>${labels[i]}<textarea name="${key}" rows="3" maxlength="20000" ${key==='conclusion'?'placeholder="What can you reasonably conclude, and within what limits?"':''}>${esc(code[key])}</textarea></label>`).join('')}<div class="actions"><button class="button primary" type="submit">Save theme conclusion</button><button class="button secondary" type="submit" name="transfer" value="yes" ${coverage.notes.length?'':'disabled'}>Save & add to proposal</button><a class="text-link" href="#research/${esc(p.id)}/proposal">Open proposal</a></div><p class="theme-save-status" role="status" aria-live="polite">Save your interpretation on this device. Proposal additions include the coded evidence and source locations.</p></form></details></div>`);const form=el.querySelector('form');try{const draft=JSON.parse(sessionStorage.getItem(draftKey(p,code.id)));if(draft&&keys.every(k=>typeof draft[k]==='string')){keys.forEach(k=>form.elements[k].value=draft[k]);el.querySelector('.theme-writing').open=true;form.querySelector('.theme-save-status').textContent='Unfinished theme draft restored. Save it before exporting a backup.'}}catch{}});
 // Table links preserve access to individual notes without forcing horizontal scrolling.
 document.querySelectorAll('.wb-synthesis-table tbody tr').forEach((row,i)=>{const n=p.evidence[i],cell=row.querySelector('th');cell.innerHTML=`<a class="text-link" href="#research/${esc(p.id)}/evidence" data-focus-evidence="${esc(n.id)}">E${i+1}</a>`});
 }
 addEventListener('rei:research-render',mount);
 document.addEventListener('click',event=>{const b=event.target.closest('[data-code-note]');if(!b)return;const form=document.querySelector('[data-wb-form="coding"]');if(!form)return;form.closest('details').open=true;form.elements.evidenceId.value=b.dataset.codeNote;form.elements.evidenceId.dispatchEvent(new Event('change',{bubbles:true}));form.scrollIntoView({block:'center',behavior:'instant'});form.elements.codeId.focus()});
 document.addEventListener('input',event=>{const form=event.target.closest('.theme-conclusion');if(!form)return;const values=Object.fromEntries(keys.map(k=>[k,form.elements[k].value]));try{sessionStorage.setItem(draftKey(project(),form.dataset.theme),JSON.stringify(values));form.querySelector('.theme-save-status').textContent='Unfinished draft kept in this tab. Save it to include it in backups.'}catch{form.querySelector('.theme-save-status').textContent='Draft is only in this form. Save before leaving this room.'}});
 document.addEventListener('submit',async event=>{const form=event.target;if(!form.matches('.theme-conclusion'))return;event.preventDefault();const p=project(),code=p.workbench.codes.find(c=>c.id===form.dataset.theme),values=Object.fromEntries(keys.map(k=>[k,form.elements[k].value])),transfer=event.submitter?.name==='transfer',status=form.querySelector('.theme-save-status'),buttons=[...form.querySelectorAll('button')],disabled=buttons.map(b=>b.disabled);buttons.forEach(b=>b.disabled=true);status.textContent='Saving…';try{const added=await C.saveTheme(p,code,values,transfer,()=>window.REIWorkbench.saveProject());try{sessionStorage.removeItem(draftKey(p,code.id))}catch{}status.textContent=transfer?(added?'Conclusion saved and added to your proposal with its evidence trail.':'Conclusion saved. This exact synthesis is already in your proposal.'):'Theme conclusion saved on this device.'}catch(error){status.textContent=error.message==='Storage full'?'Could not save. Your text is still here; retry before leaving.':error.message||'Could not save. Your text is still here; retry before leaving.'}finally{buttons.forEach((b,i)=>b.disabled=disabled[i])}});
})();
